public sealed class TicketWorkflow(AppDbContext db)
{
    public async Task<int> CrearAsync(string titulo, CancellationToken ct)
    {
        var ticket = new Ticket { Titulo = titulo };
        db.Tickets.Add(ticket);
        await db.SaveChangesAsync(ct);
        return ticket.Id;
    }
}

